#!/usr/bin/env python3
import csv,hashlib,json,os,resource,signal,subprocess,sys,time,re
from pathlib import Path
from datetime import datetime,timezone
OUT=Path(__file__).resolve().parent;ROOT=Path('/root/Openfhe_PE')
sys.path.insert(0,'/root/benchmarks/main_original_full_encrypted_shapes_20261025/tools');import monitor_helpers as mon
def now():return datetime.now(timezone.utc).isoformat()
def save(path,data):
 t=path.with_suffix(path.suffix+'.tmp');t.write_text(json.dumps(data,indent=2)+'\n');t.replace(path)
operators={}
def parse(text):
 for m in re.finditer(r'BASELINE_OPERATOR (.+)',text):
  r=dict(s.split('=',1) for s in m[1].split());r={k:(v if k=='operator' else float(v)) for k,v in r.items()};r['stage']=int(r['stage']);operators[(r['stage'],r['operator'])]=r
 if operators:
  with (OUT/'operators.csv').open('w',newline='') as f:
   records=sorted(operators.values(),key=lambda r:(r['stage'],r['operator']=='activation'));w=csv.DictWriter(f,fieldnames=list(records[0]));w.writeheader();w.writerows(records)
def report(status='running',result=None):
 lines=['# Original baseline repeated for six stages: ring 16384','',f'Status: {status}; updated UTC: {now()}','',
 'Main-branch source commit 08e56ef. A standalone wrapper extends only baseline_test from one to six Conv2d_C + Relu_appx pairs. Operator implementations and original initialization are unchanged; Network timing instrumentation adds level/RSS logging outside forward timers. The main repository worktree remains clean. Exact wrapper/instrumentation patches are retained in source/.','',
 'Ring dimension 16384; 8192 slots; 96 threads. Six fully encrypted 64→64 convolutions, kernel 3×3, stride 1, no padding. Input is 64×56×56; output widths are 54,52,50,48,46,44. The first-layer synthetic inputs/weights use the original rand()/9 generators; subsequent stages generate new weights with the same routine. This is the requested repeated baseline, not the first six ResNet layers or a trained classifier.','',
 'The original Conv2d_C filter-vector allocation is corrected to the full ciphertext slot count. VALID_INDEX_MAP retains the original input pitch across stages; allocating only the shrinking H×W causes out-of-bounds writes from stage 2. The first failed run is retained in attempt_original_bounds/. This safety fix does not repack slots or alter convolution arithmetic.', '', 'Original parameters are preserved: depth 23, 30/40-bit moduli, HYBRID digits 3; bootstrap depth calculation uses {3,3}, actual setup {4,3}, correction factor 10. Both bootstrap and scheme-switch keys are always generated by the old main. Each activation evaluates the original unnormalized degree-6 polynomial and invokes EvalBootstrap in the channel-parallel loop. No forced depletion, normalization or adaptive parameter changes are inserted. A bootstrap call may return its input without refreshing; output levels are recorded so this can be inspected. Six stages may expose original depth/precision limitations; failures must not be reported as successful six-stage inference.','',
 'RSS is sampled every 0.5 seconds; operator timings come from original forward timers. Process wall and lifetime peak come from GNU time. Setup/preparation, operator and verification phases are distinguished from log milestones. No network measurement or allocator trimming. The final plaintext reference follows six convolutions with exact ReLU; its relative loss is not a polynomial arithmetic check.','',
 '| Stage | Operator | Output width | Time (s) | Ciphertexts | Level / towers / scale degree | RSS after call (GiB) | Lifetime peak after call (GiB) |','|---:|---|---:|---:|---:|---|---:|---:|']
 for r in sorted(operators.values(),key=lambda r:(r['stage'],r['operator']=='activation')):
  lines.append(f"| {r['stage']} | {r['operator']} | {56-2*r['stage']} | {r['ms']/1000:.3f} | {r['ciphertexts']:g} | {r['level']:g} / {r['towers']:g} / {r['noise_degree']:g} | {r['rss_gib']:.3f} | {r['peak_gib']:.3f} |")
 if result:
  lines+=['','## Process result','',f"Exit code: {result['exit_code']}; completed operator calls: {result['completed_operators']}/12; process wall: {result['wall_s']:.3f} s; whole-process peak RSS: {result['whole_process_peak_gib']:.3f} GiB."]
  if result.get('error_lines'):lines+=['','Recorded error messages:','']+['- '+s for s in result['error_lines']]
 temp=OUT/'REPORT.md.tmp';temp.write_text('\n'.join(lines)+'\n');temp.replace(OUT/'REPORT.md')
def main():
 resource.setrlimit(resource.RLIMIT_CORE,(0,0));binary=OUT/'build/baseline_six'
 cmd=[str(binary),'--model','baseline_test','--ringDim','16384','--batch','8192','--act','1','--top','0','--bottom','55','--left','0','--right','55','--nums','64','--baseline-layers','6']
 save(OUT/'configuration.json',dict(command=cmd,source_branch='main',bounds_fix='filter vectors sized to ciphertext slots; retained-index bounds checked',source_commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),ring=16384,slots=8192,depth=23,scale_bits=30,first_bits=40,digits=3,threads=96,stages=6,channels=64,input_width=56,bootstrap_setup_budget=[4,3],both_key_families=True,binary_sha256=hashlib.sha256(binary.read_bytes()).hexdigest()))
 report();env=os.environ.copy();env.update(LD_LIBRARY_PATH='/root/local/openFHE/lib:/root/local/cnpy/lib',OMP_NUM_THREADS='96',OMP_DYNAMIC='FALSE',OMP_MAX_ACTIVE_LEVELS='1')
 start=time.monotonic();samples=[];phase='key_setup';stage=0;offset=0;lastreport=0;pressure=False
 with (OUT/'run.log').open('w') as log,(OUT/'rss.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=['utc','elapsed_s','phase','layer','rss_gib','process_peak_gib','threads']);w.writeheader()
  proc=subprocess.Popen(['/usr/bin/time','-f','wall_seconds=%e\npeak_rss_kib=%M\nexit_code=%x','-o',str(OUT/'time.txt'),*cmd],cwd=ROOT/'build',env=env,stdout=log,stderr=subprocess.STDOUT,start_new_session=True)
  while proc.poll() is None:
   try:
    with (OUT/'run.log').open(errors='replace') as reader:reader.seek(offset);text=reader.read();offset=reader.tell()
    parse(text)
    if 'Shape of input_3d:' in text:phase='input_preparation'
    for m in re.finditer(r'BASELINE_BEGIN stage=(\d+) operator=(\w+)',text):stage=int(m[1]);phase='server_conv' if m[2]=='convolution' else 'server_relu'
    kids=Path(f'/proc/{proc.pid}/task/{proc.pid}/children').read_text().split();info=mon.rss(int(kids[0])) if kids else {}
    if 'VmRSS' in info:
     r=dict(utc=now(),elapsed_s=time.monotonic()-start,phase=phase,layer=stage,rss_gib=info['VmRSS']/1024**2,process_peak_gib=info['VmHWM']/1024**2,threads=info['Threads']);samples.append(r);w.writerow(r);f.flush();save(OUT/'live.json',dict(status='running',model_pid=int(kids[0]),runner_pid=os.getpid(),**r))
    if mon.available()<12:
     pressure=True;os.killpg(proc.pid,signal.SIGTERM)
     try:proc.wait(timeout=15)
     except subprocess.TimeoutExpired:os.killpg(proc.pid,signal.SIGKILL);proc.wait()
    if time.monotonic()-lastreport>30:report();lastreport=time.monotonic()
   except (OSError,KeyError,ValueError):pass
   time.sleep(.5)
  code=proc.wait()
 text=(OUT/'run.log').read_text(errors='replace');parse(text)
 metrics=dict(x.split('=',1) for x in (OUT/'time.txt').read_text().splitlines() if '=' in x)
 result=dict(status='success' if code==0 and len(operators)==12 else 'memory_pressure' if pressure else 'failed',exit_code=code,finished_utc=now(),completed_operators=len(operators),last_stage=stage,last_phase=phase,wall_s=float(metrics.get('wall_seconds',time.monotonic()-start)),whole_process_peak_gib=float(metrics.get('peak_rss_kib',0))/1024**2,error_lines=[x.strip() for x in text.splitlines() if any(k in x for k in ('what():','terminate called','error is too high','insufficient','not enough','malloc():','Assertion'))][-8:],phase_memory={p:mon.summarize([s for s in samples if s['phase']==p]) for p in ['key_setup','input_preparation','server_conv','server_relu']})
 save(OUT/'result.json',result);save(OUT/'live.json',result);report(result['status'],result);print(json.dumps(result),flush=True)
if __name__=='__main__':main()
